-- Module 5: consent and the marketing list.
--   marketing_exports        – one row per download of the email list (who, when, filters, count)
--   contacts.do_not_contact_* – when and by whom do-not-contact was set ("requested 21 Oct 2026")
--   consents.source          – becomes a pick-list; existing values are mapped onto it first
-- The triggers and the view changes are in 0010.
CREATE TABLE "marketing_exports" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "marketing_exports_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"filters" jsonb NOT NULL,
	"summary" text NOT NULL,
	"row_count" integer NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"created_by" bigint,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_by" bigint,
	"deleted_at" timestamp with time zone,
	"deleted_by" bigint
);
--> statement-breakpoint
ALTER TABLE "contacts" ADD COLUMN "do_not_contact_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "contacts" ADD COLUMN "do_not_contact_by" bigint;--> statement-breakpoint
ALTER TABLE "marketing_exports" ADD CONSTRAINT "marketing_exports_created_by_staff_users_id_fk" FOREIGN KEY ("created_by") REFERENCES "public"."staff_users"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "marketing_exports" ADD CONSTRAINT "marketing_exports_updated_by_staff_users_id_fk" FOREIGN KEY ("updated_by") REFERENCES "public"."staff_users"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "marketing_exports" ADD CONSTRAINT "marketing_exports_deleted_by_staff_users_id_fk" FOREIGN KEY ("deleted_by") REFERENCES "public"."staff_users"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "marketing_exports_created_idx" ON "marketing_exports" USING btree ("created_at" DESC NULLS LAST) WHERE "marketing_exports"."deleted_at" IS NULL;--> statement-breakpoint
ALTER TABLE "contacts" ADD CONSTRAINT "contacts_do_not_contact_by_staff_users_id_fk" FOREIGN KEY ("do_not_contact_by") REFERENCES "public"."staff_users"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint

-- Guests already on do-not-contact: the best date on file is their last update.
-- The audit trigger is paused so this doesn't show as a change made today.
ALTER TABLE "contacts" DISABLE TRIGGER "t_contacts_audit";--> statement-breakpoint
UPDATE "contacts" SET "do_not_contact_at" = "updated_at", "do_not_contact_by" = "updated_by"
 WHERE "status" = 'do_not_contact';--> statement-breakpoint
ALTER TABLE "contacts" ENABLE TRIGGER "t_contacts_audit";--> statement-breakpoint

-- Map the free-text sources (the imported list says "wix") onto the pick-list.
-- Anything unrecognised becomes 'other', with the original text kept in evidence.
UPDATE "consents" SET "source" = NULL WHERE trim("source") = '';--> statement-breakpoint
UPDATE "consents" k SET
  "evidence" = CASE WHEN m.mapped = 'other' AND m.key <> 'other'
                    THEN concat_ws(' | ', k."evidence", 'Source: ' || k."source") ELSE k."evidence" END,
  "source" = m.mapped
FROM (
  SELECT id, key, CASE key
           WHEN 'wix' THEN 'wix'
           WHEN 'website' THEN 'website_form' WHEN 'website_form' THEN 'website_form' WHEN 'web_form' THEN 'website_form'
           WHEN 'booking' THEN 'booking_form' WHEN 'booking_form' THEN 'booking_form'
           WHEN 'check_in' THEN 'check_in_form' WHEN 'checkin' THEN 'check_in_form' WHEN 'check_in_form' THEN 'check_in_form'
           WHEN 'checkin_form' THEN 'check_in_form'
           WHEN 'whatsapp' THEN 'whatsapp'
           WHEN 'in_person' THEN 'in_person'
           WHEN 'unsubscribe' THEN 'email_unsubscribe' WHEN 'email_unsubscribe' THEN 'email_unsubscribe'
           ELSE 'other' END AS mapped
    FROM (SELECT id, trim(BOTH '_' FROM regexp_replace(lower("source"), '[^a-z]+', '_', 'g')) AS key
            FROM "consents" WHERE "source" IS NOT NULL) s
) m
WHERE m.id = k.id AND m.mapped IS DISTINCT FROM k."source";--> statement-breakpoint
ALTER TABLE "consents" ADD CONSTRAINT "consents_source_check" CHECK ("consents"."source" IN ('wix', 'website_form', 'booking_form', 'check_in_form', 'whatsapp', 'in_person', 'email_unsubscribe', 'do_not_contact', 'other'));
